--   chrome copy (intro, meta description, key-fact triples, benchmarks/
--   prose split, page micro-copy) so the shared template can reproduce the
--   live pages without loss. Also corrects the north-channel faqs jsonb:
--   ratification sits with the ILDSA, not "the Infinity Channel
--   Association" (Dave confirmed 2026-08-14; Infinity Channel Swimming is
--   a piloting/support operation).

-- Requested by:
--   Dave (SEO acquisition layer, increment 3)

-- ----------------------------------------------------------------
-- PRE-CHECKS — run on the READ-ONLY connection BEFORE applying.
-- ----------------------------------------------------------------
-- Expect 10 (all content-bearing crossings, english-channel excluded):
-- SELECT count(*) FROM public.crossings WHERE slug IN ('catalina-channel', 'cook-strait', 'false-bay', 'jersey-to-france', 'manhattan-island', 'molokai-channel', 'north-channel', 'rottnest-channel', 'strait-of-gibraltar', 'tsugaru-strait');
-- Expect 1 (the stale ICA claim still present before applying):
-- SELECT count(*) FROM public.crossings WHERE slug = 'north-channel' AND faqs::text LIKE '%Infinity Channel Association%';

-- ----------------------------------------------------------------
-- BACKUP — required: this UPDATEs existing preparation + faqs values.
-- ----------------------------------------------------------------
CREATE TABLE IF NOT EXISTS _bak_20260814_crossings AS SELECT * FROM public.crossings;

-- ----------------------------------------------------------------
-- MIGRATION — applied only after Dave types "apply".
-- ----------------------------------------------------------------
BEGIN;

ALTER TABLE public.crossings
  ADD COLUMN IF NOT EXISTS intro text,
  ADD COLUMN IF NOT EXISTS seo_description text,
  ADD COLUMN IF NOT EXISTS key_facts jsonb,
  ADD COLUMN IF NOT EXISTS prep_benchmarks jsonb,
  ADD COLUMN IF NOT EXISTS page_copy jsonb;

COMMENT ON COLUMN public.crossings.intro           IS 'Hero intro paragraph, verbatim from the page — the sentence doing the most SEO work';
COMMENT ON COLUMN public.crossings.seo_description IS 'Meta description, verbatim from the page';
COMMENT ON COLUMN public.crossings.key_facts       IS '[{label, val, note}] — the Key Facts cards verbatim; scalar columns stay canonical for queries';
COMMENT ON COLUMN public.crossings.prep_benchmarks IS 'Training-benchmark checklist items; preparation column holds the prose paragraphs only';
COMMENT ON COLUMN public.crossings.page_copy       IS 'Bespoke page micro-copy: eyebrow, difficulty_label, section titles, readiness + CTA blurbs';

UPDATE public.crossings SET
  intro = 'One of the original marathon swims and a member of the Triple Crown of Open Water Swimming. The 33km crossing from Catalina Island''s Two Harbors to the California mainland demands cold water tolerance, shark awareness, and relentless mental fortitude.',
  seo_description = 'Complete guide to swimming the Catalina Channel — 33km from Two Harbors to the California mainland. Water temps, season, hazards, and readiness checker.',
  key_facts = '[{"label":"Distance","val":"33 km","note":"Two Harbors, Catalina Island to Pt Vicente Lighthouse, Palos Verdes Peninsula"},{"label":"Water Temperature","val":"14–20°C","note":"Coldest in early season (Jun); warmest Aug–Sep. Thermocline upwelling can drop temps suddenly mid-crossing."},{"label":"Swim Season","val":"Jun – Oct","note":"Peak conditions July–September. Most attempts start between midnight and 3am to time tidal currents."},{"label":"Average Finish Time","val":"12–14 hrs","note":"Record: 7h 11m (Forrest Nelson, 2021). Most swimmers finish in 11–16 hours."},{"label":"Governing Body","val":"CCSF","note":"Catalina Channel Swimming Federation. All official attempts must be sanctioned and use an approved observer."},{"label":"Difficulty","val":"Very Hard","note":"Part of the Triple Crown alongside the English Channel and Manhattan Island swim. Completion rate roughly 65–70%."}]'::jsonb,
  prep_benchmarks = '["Longest single open water swim of at least 20–25km before your attempt.","Weekly training volume of 40–50km in the 3 months prior to the crossing.","Sustained swimming in water below 16°C — cold acclimation is non-negotiable.","Night swimming experience: most crossings start in darkness and last until late morning.","Feed practice from a moving boat — you will need to eat and drink every 30–45 minutes without stopping."]'::jsonb,
  preparation = '["Most coaches recommend a 12–18 month preparation window for first-time Catalina Channel aspirants. The key physical demands are different from pool marathon swimming: you need cold acclimatisation more than raw speed, and the ability to maintain your pace when jellies sting and the thermocline kicks in at hour six. Build a base of long open water swims through winter to train your body to stay efficient in 14–16°C water.","Nutrition is a critical discipline. Over a 12–14 hour swim you will consume 4,000–6,000 calories, primarily from liquid feeds (maltodextrin-based drinks, warm broth, gels). Practice your feed protocol extensively in training so it becomes automatic. Your escort crew — captain, observer, and at least two support people — need to be briefed on the CCSF rules and your feeding schedule. Engage a local Catalina crew well in advance; experienced captains book out a year ahead."]'::jsonb,
  page_copy = '{"eyebrow":"California, USA — Pacific Ocean","difficulty_label":"Very Hard","challenge_title":"What Makes It Challenging","benchmarks_label":"Training Benchmarks","readiness_title":"Catalina Readiness Check","readiness_blurb":"Enter your current training stats to get an indicative readiness score for the Catalina Channel. This is a rough guide only — discuss your preparation with an experienced marathon swim coach.","cta_title":"Track Your Cold Water Training","cta_blurb":"Log every open water swim, track water temperatures, and build the data you need to prove cold acclimatisation for your Catalina Channel application."}'::jsonb,
  updated_at = now()
WHERE slug = 'catalina-channel';

UPDATE public.crossings SET
  intro = 'The treacherous stretch of water separating New Zealand''s South and North Islands is one of the most unpredictable crossings on earth. Cold water, violent tidal currents, and weather that can change within minutes make Cook Strait one of the hardest Oceans Seven swims.',
  seo_description = 'Complete guide to swimming Cook Strait — ~26km between New Zealand''s South and North Islands. One of the Oceans Seven, with 10–15°C water and powerful tidal currents.',
  key_facts = '[{"label":"Distance","val":"~26 km","note":"South Island (Turakirae Head area) to North Island (Oteranga Bay, Wellington). The actual distance swum is often significantly longer due to current drift."},{"label":"Water Temperature","val":"10–15°C","note":"One of the coldest of the Oceans Seven crossings. The Southland Current brings sub-Antarctic water into the strait. Cold tolerance is a critical preparation requirement."},{"label":"Swim Season","val":"Jan – Mar","note":"Southern hemisphere summer offers the best weather window. Even within this period, swims are highly weather-dependent — days-long waits for a suitable window are common."},{"label":"Average Finish Time","val":"8–14 hrs","note":"Record: 7h 20m (Philip Rush, 1988). Current drift can add hours to the swim — some attempts cover 50km+ of actual distance navigating currents."},{"label":"Governing Body","val":"CSSA","note":"Cook Strait Swimming Association. Ratified swims require CSSA sanctioning, an approved observer, and a registered pilot who knows the strait''s currents intimately."},{"label":"Difficulty","val":"Extreme","note":"One of the Oceans Seven and among the most weather-affected crossings in the world. The low success rate is primarily due to weather aborts, not swimmer fitness."}]'::jsonb,
  prep_benchmarks = '["Cold water acclimatisation to sustained swimming in 10–13°C — this is the defining preparation challenge for Cook Strait.","Longest single open water swim of at least 20km before your attempt.","Weekly volume of 40–50km in the 3 months prior, with regular cold water sessions through winter.","Experience in rough, confused seas — swell training in exposed ocean conditions, not just harbour swims.","Psychological preparation for extended weather waits — many aspiring Cook Strait swimmers travel to Wellington and wait 1–2 weeks for a suitable window."]'::jsonb,
  preparation = '["Cold water acclimatisation is the most important and most underestimated aspect of Cook Strait preparation. At 10–12°C, the water is cold enough to cause significant pain to unacclimated swimmers within the first hour, and progressive hypothermia over the 8–14 hours a crossing typically takes. You must train your body to function efficiently — maintaining pace, breathing rhythm, and mental clarity — in water this cold. This takes months of year-round cold water exposure, not a few preparatory dips before you fly to Wellington.","Plan for a flexible travel schedule. The weather window in Cook Strait is notoriously narrow and unpredictable. Most experienced Oceans Seven chasers allocate 2–3 weeks in New Zealand and treat each day as a potential go day. This requires flexibility from your employer, family, and support crew. The CSSA and your pilot will monitor conditions daily and call the start typically 12–24 hours in advance. Some swimmers have made multiple trips to Wellington before conditions finally aligned for a successful attempt."]'::jsonb,
  page_copy = '{"eyebrow":"New Zealand — Oceans Seven","difficulty_label":"Extreme","challenge_title":"What Makes It Challenging","benchmarks_label":"Training Benchmarks","readiness_title":"Cook Strait Readiness Check","readiness_blurb":"Enter your current training stats. Cook Strait weights cold water tolerance very heavily — even physically strong swimmers who haven''t trained in 10–13°C water are not ready for this crossing.","cta_title":"Track Your Cold Water Progress","cta_blurb":"Log every cold water session, record temperatures, and build the evidence of cold acclimatisation you''ll need for your Cook Strait application."}'::jsonb,
  updated_at = now()
WHERE slug = 'cook-strait';

UPDATE public.crossings SET
  intro = 'Miller''s Point to Gordon''s Bay — approximately 28 km across the open waters of False Bay. One of South Africa''s most demanding and storied open water crossings.',
  seo_description = 'Everything you need to know about swimming False Bay — distance, water temperature, great white sharks, currents, and how to prepare for South Africa''s ultimate open water crossing.',
  key_facts = '[{"label":"Distance","val":"~28 km","note":"Miller''s Point (Simon''s Town) to Gordon''s Bay. Route may vary based on conditions."},{"label":"Water Temperature","val":"14–18°C","note":"Summer (Jan–Mar) sees the warmest water. The bay can be cold on its western side where Atlantic upwelling intrudes."},{"label":"Swim Season","val":"Jan – Mar","note":"Southern hemisphere summer. Sea state is most settled in early morning; afternoon south-easterly wind typically builds."},{"label":"Current","val":"Variable","note":"False Bay does not have strong tidal streams but localised currents near Cape Point can push swimmers off course."},{"label":"Wildlife","val":"Great whites","note":"False Bay has one of the world''s highest concentrations of great white sharks. Shark watch boats are required for any crossing attempt."},{"label":"Difficulty","val":"Extreme","note":"Distance, cold, afternoon wind swell and shark risk combine to make this one of the hardest crossings in southern Africa."}]'::jsonb,
  prep_benchmarks = '["Peak weekly volume: 40–55 km/week in the 12 weeks before your attempt","Longest training swim: 6–8 hours continuous in open water","Cold acclimatisation: regular swims in 14–16°C water — the Atlantic side of the Cape Peninsula is ideal","Ocean swimming experience: extensive experience with Cape conditions, swell and current","Night swimming optional but beneficial — start times before dawn"]'::jsonb,
  preparation = '["Cape Town''s Atlantic Seaboard and False Bay both offer excellent training grounds. DUC (Down Under Club) at Clifton provides cold Atlantic open water experience. False Bay spots like St James, Fish Hoek and Gordon''s Bay allow swimmers to familiarise themselves with the bay''s characteristics.","Planning a False Bay crossing requires: permits from the relevant marine authority, a dedicated support team with shark watch boats, a meteorological briefing from a local specialist, and an emergency plan. The crossing is not undertaken lightly and is generally only attempted by swimmers with extensive local open water credentials."]'::jsonb,
  page_copy = '{"eyebrow":"Cape Town · South Africa","difficulty_label":"Extreme","challenge_title":"What Makes It So Hard","benchmarks_label":"Training Benchmarks","readiness_title":"Check My False Bay Readiness","readiness_blurb":"Enter your current training state for an indicative readiness score.","cta_title":"Track your False Bay preparation","cta_blurb":"Log open water swims in Cape Town, track cold water exposure across the Cape Peninsula and build a readiness record with SwimLoading."}'::jsonb,
  updated_at = now()
WHERE slug = 'false-bay';

UPDATE public.crossings SET
  intro = 'The crossing from St Ouen''s Bay on Jersey''s west coast to Cap de la Hague in Normandy spans ~22km of some of the world''s most tidally complex waters. The Channel Islands experience tidal ranges of up to 12 metres — and the currents that result from them dominate every aspect of this crossing.',
  seo_description = 'Complete guide to swimming Jersey to France — ~22km from St Ouen''s Bay, Jersey to Cap de la Hague, Normandy. Strong tidal currents, 14–18°C, and one of the Channel Islands'' great open water challenges.',
  key_facts = '[{"label":"Distance","val":"~22 km","note":"St Ouen''s Bay, Jersey (west coast) to Cap de la Hague, Normandy. Actual distance swum often exceeds 25–30km due to tidal movement during the crossing."},{"label":"Water Temperature","val":"14–18°C","note":"Warmest in August–September. The Channel Islands sit in the English Channel, which is significantly colder than the Mediterranean — cold acclimatisation is essential."},{"label":"Swim Season","val":"Jul – Sep","note":"The tidal window narrows the viable swimming season significantly. Neap tides in July–September offer the most manageable current conditions for crossing attempts."},{"label":"Average Finish Time","val":"6–10 hrs","note":"Varies enormously depending on tidal timing. A well-timed crossing with neap tides can be completed in 6–7 hours; a poorly timed one may never reach France regardless of swimmer fitness."},{"label":"Tidal Range","val":"Up to 12 m","note":"Jersey has one of the largest tidal ranges in the world — second only to the Bay of Fundy. The currents generated by this range are the defining challenge of the crossing."},{"label":"Difficulty","val":"Very Hard","note":"Tidal current management makes this one of the most technically demanding crossings in Europe. A pilot with deep local knowledge of Channel Islands tidal patterns is non-negotiable."}]'::jsonb,
  prep_benchmarks = '["Longest single open water swim of at least 15–18km in cold water (below 17°C) before your attempt.","Weekly volume of 30–40km maintained through the summer, with at least one long cold water sea swim per week.","Cold acclimatisation: sustained swimming in 14–16°C water for 5+ hours without a wetsuit — this is the critical physical test for the crossing.","Tidal current swimming experience — practise in tidal estuaries or tidal pools to develop an intuitive sense of working with and against water movement.","English Channel qualifying swim is a useful benchmark — many Jersey-to-France aspirants complete an EC crossing first to establish their cold water and long-distance credentials."]'::jsonb,
  preparation = '["Cold water tolerance is the most important physical preparation requirement for the Jersey to France crossing. At 14–16°C, the water is significantly colder than most open water swimming destinations, and maintaining efficient stroke mechanics over 6–10 hours in this temperature requires months of progressive cold water exposure. Start your cold acclimatisation in winter — swimming through the colder months rather than stopping and restarting in spring is far more effective at building genuine cold tolerance.","Pilot selection is the most consequential decision you will make for this crossing. Find a local Jersey or Normandy pilot with specific experience of this crossing or equivalent Channel Islands tidal waters. They need to understand the local tidal diamond data, the behaviour of currents around the Paternosters reef system north of Jersey, and the timing of the Alderney Race. A pilot who knows the English Channel well but has no Channel Islands experience is not sufficient — the tidal complexity here is of a different character to the Dover Strait."]'::jsonb,
  page_copy = '{"eyebrow":"Channel Islands — English Channel","difficulty_label":"Very Hard","challenge_title":"What Makes It Challenging","benchmarks_label":"Training Benchmarks","readiness_title":"Jersey–France Readiness Check","readiness_blurb":"Enter your current training stats. This crossing places heavy demands on cold water tolerance and sustained pacing — it is the tidal complexity and cold that separate successful from unsuccessful attempts, not raw distance.","cta_title":"Log Your Cold Water Training","cta_blurb":"Track every cold water session and temperature log as you build toward a Jersey to France attempt. Documented cold water experience is essential for any serious crossing proposal."}'::jsonb,
  updated_at = now()
WHERE slug = 'jersey-to-france';

UPDATE public.crossings SET
  intro = 'A ~48km circumnavigation of Manhattan Island through the Hudson, Harlem, and East Rivers, completing the Triple Crown of Open Water Swimming. Tidal timing is everything — the swim only works if you ride the currents correctly.',
  seo_description = 'Complete guide to the Manhattan Island Marathon Swim — a ~48km circumnavigation of Manhattan through the Hudson, Harlem, and East Rivers. Part of the Triple Crown of Open Water Swimming.',
  key_facts = '[{"label":"Distance","val":"~48 km","note":"The circumnavigation covers the full perimeter of Manhattan Island — Hudson River south, Battery Park turn, East River north, Harlem River west, and back to start."},{"label":"Water Temperature","val":"16–24°C","note":"Temperatures peak in July–August. The Hudson and East Rivers can differ by 2–3°C. Early season (June) can be as low as 16°C."},{"label":"Swim Season","val":"Jun – Sep","note":"The official MIMS event is held annually in June. Tidal windows for the circumnavigation are calculated months in advance and are non-negotiable."},{"label":"Average Finish Time","val":"7–9 hrs","note":"Record: 5h 45m (Shelley Taylor-Smith, 1995). Most competitors finish in 7–10 hours. The tidal window closes around 9–10 hours."},{"label":"Governing Body","val":"MIMS","note":"Manhattan Island Marathon Swim organisation. Sanctioned swims require MIMS approval, an official observer, and coordination with the US Coast Guard and NYC port authorities."},{"label":"Difficulty","val":"Very Hard","note":"Part of the Triple Crown. The raw distance is manageable for experienced marathon swimmers, but tidal and current management makes it a genuine navigation and pacing challenge."}]'::jsonb,
  prep_benchmarks = '["Longest single open water swim of at least 30km — the sheer distance of MIMS requires proven ultra-distance capacity.","Weekly training volume of 50–60km in the 3 months prior to your attempt.","River and current swimming experience — practise in tidal or current-affected water to understand drift management and pacing adjustments.","Night swimming experience — many MIMS starts are in early morning darkness for tidal window reasons.","Feed efficiency: eating and drinking must not break your stroke rhythm. Practise continuous swimming with feed stops under 15 seconds."]'::jsonb,
  preparation = '["The Manhattan Island circumnavigation is unusual among marathon swims in that speed matters more than in channel crossings — not because of distance, but because of the tidal window. Swimmers who fall behind pace risk missing the current transition at Hell Gate, which effectively ends the attempt. Your preparation should include tempo sets and race-pace training at realistic speeds, not just slow ultra-distance endurance work. Know your pace per kilometre in open water with high confidence.","Logistics preparation is as demanding as physical preparation. MIMS requires coordination with the US Coast Guard, New York City Department of Parks and Recreation, and port authorities. You need a MIMS-approved observer, a suitable escort vessel, and a pilot familiar with New York Harbor tidal patterns. Most swimmers apply to MIMS a year in advance for an official event slot, rather than attempting an independent sanctioned swim. The official annual MIMS event in June handles much of the permitting complexity on behalf of entrants."]'::jsonb,
  page_copy = '{"eyebrow":"New York City, USA — Triple Crown","difficulty_label":"Very Hard","challenge_title":"What Makes It Challenging","benchmarks_label":"Training Benchmarks","readiness_title":"MIMS Readiness Check","readiness_blurb":"Enter your current training stats for an indicative readiness score. Manhattan is one of the longest sanctioned marathon swims in the world — distance and pacing experience are paramount.","cta_title":"Track Your Training Data","cta_blurb":"Log open water sessions, water temperatures, and conditions as you build toward your Triple Crown ambitions. SwimLoading keeps the record so you can focus on the swimming."}'::jsonb,
  updated_at = now()
WHERE slug = 'manhattan-island';

UPDATE public.crossings SET
  intro = 'Known in Hawaiian as Ka''iwi Channel — the Channel of Bones — this 42km crossing from Molokai to Oahu is one of the most physically demanding of the Oceans Seven. Warm water conceals deep Pacific swells, box jellyfish blooms, and one of the world''s highest concentrations of tiger sharks.',
  seo_description = 'Complete guide to swimming the Molokai Channel (Ka''iwi Channel) — ~42km from Molokai to Oahu, Hawaii. One of the Oceans Seven with box jellyfish, sharks, and powerful Pacific swells.',
  key_facts = '[{"label":"Distance","val":"~42 km","note":"From Laau Point, Molokai to Sandy Beach, Oahu. Currents frequently push swimmers well off a straight line — actual distance swum is often 45–50km."},{"label":"Water Temperature","val":"24–28°C","note":"The warmest of the Oceans Seven crossings. While comfortable for swimming, warm water supports year-round jellyfish presence and reduces any cold-shock risk management tool."},{"label":"Swim Season","val":"Apr – Sep","note":"Summer months offer the best swell windows. The channel never has flat conditions — summer swells are smaller (1–2m) than winter trade-wind swells (3–5m)."},{"label":"Average Finish Time","val":"14–18 hrs","note":"Record: 12h 16m (Penny Palfrey, 2009). Most swimmers require 15–20 hours. The distance and swell exposure make it one of the longest Oceans Seven crossings in elapsed time."},{"label":"Wildlife","val":"Sharks & Jellies","note":"Tiger sharks and box jellyfish (Alatina alata) are the two primary wildlife hazards. Box jellyfish bloom on a monthly lunar cycle — planning around this is essential."},{"label":"Difficulty","val":"Extreme","note":"One of the Oceans Seven. The combination of distance, relentless Pacific swell, jellyfish risk, and psychological demands of 15+ hours in deep open ocean make this a supreme challenge."}]'::jsonb,
  prep_benchmarks = '["Longest single open water swim of at least 30km — the Ka''iwi Channel demands proven ultra-distance capacity in rough water.","Weekly training volume of 50–60km maintained for at least 3–4 months prior to the attempt.","Sustained rough water swimming — you must be able to maintain efficient stroke mechanics in 1.5–2m swell for 15+ hours.","Night swimming experience: most attempts start between midnight and 3am and run through the following day.","Jellyfish sting response: know your personal reaction to jellyfish stings and have a treatment protocol agreed with your crew and medical advisor."]'::jsonb,
  preparation = '["Unlike most Oceans Seven crossings, the Molokai Channel does not require cold water acclimatisation — at 24–28°C the water is comfortably warm throughout the season. The preparation focus instead shifts entirely to ultra-distance endurance in rough ocean conditions. Swimmers who train primarily in pools or protected harbours often find the relentless Pacific swell far more energy-consuming than their training suggested. Build in as much open ocean swell swimming as possible in the months before your attempt, even if this means travelling to exposed coastlines for training camps.","Nutrition over 15–20 hours is a significant logistical challenge. Most Ka''iwi Channel swimmers consume 600–800 calories per hour in liquid form, primarily carbohydrate-based drinks with sodium supplementation. Crew briefing is critical — they need to maintain your feeding schedule precisely, monitor your stroke count and pace, and manage the boat safely in open Pacific conditions. Engage an experienced Hawaiian crew well in advance; local knowledge of the channel''s currents is an enormous advantage for your pilot in choosing the correct start angle and adjusting for drift during the swim."]'::jsonb,
  page_copy = '{"eyebrow":"Hawaii, USA — Oceans Seven","difficulty_label":"Extreme","challenge_title":"What Makes It Challenging","benchmarks_label":"Training Benchmarks","readiness_title":"Ka''iwi Channel Readiness Check","readiness_blurb":"Enter your current training stats. The Molokai Channel scores high on distance and rough water demands — warm water means cold tolerance is less critical, but ultra-distance capacity in open ocean is paramount.","cta_title":"Log Every Ocean Swim","cta_blurb":"Build your open water record and track conditions across every training session as you prepare for the Ka''iwi Channel challenge."}'::jsonb,
  updated_at = now()
WHERE slug = 'molokai-channel';

UPDATE public.crossings SET
  intro = 'Donaghadee, Northern Ireland to Portpatrick, Scotland. The coldest and most feared crossing in the Oceans Seven — and the hardest open water swim on earth.',
  seo_description = 'Everything you need to know about swimming the North Channel — distance, water temperature, jellyfish, tides, and how to prepare for the world''s toughest open water crossing.',
  key_facts = '[{"label":"Distance","val":"~35 km","note":"Straight-line distance. Tidal drift means swimmers cover 38–45 km in the water."},{"label":"Water Temperature","val":"10–14°C","note":"Peak season (Aug–Sep) averages 12–14°C. Water below 10°C has been recorded in July."},{"label":"Swim Season","val":"Jul – Sep","note":"Most successful crossings happen in late July and August. September sees more settled weather but cooling water."},{"label":"Average Crossing Time","val":"10–14 hrs","note":"Record: 9 hours 32 minutes (Donaghadee to Portpatrick). Many crossings take 12+ hours."},{"label":"Governing Body","val":"ILDSA","note":"The Irish Long Distance Swimming Association (ILDSA) sanctions and ratifies crossings. Piloting and support operations such as Infinity Channel Swimming run the escort boats."},{"label":"Success Rate","val":"~40%","note":"Lower than the English Channel. Cold and jellyfish are the primary causes of failed attempts."}]'::jsonb,
  prep_benchmarks = '["Peak weekly volume: 50–65 km/week in the 12 weeks before your attempt","Longest training swim: 8–10 hours continuous (not just distance — time matters)","Cold acclimatisation: regular swims at or below 12°C for 6+ months","Night swimming: at least 2–3 night ocean sessions in the months before (jellyfish are worse at night)","Feeding practice: comfortable taking feeds at 45-minute intervals without stopping"]'::jsonb,
  preparation = '["Most North Channel swimmers train in Ireland or the west coast of Scotland from October through the winter to build cold tolerance in conditions that replicate what they''ll face on crossing day. Dover Harbour is useful for English Channel prep; the North Channel requires Irish Sea cold.","An ILDSA-ratified attempt typically requires completing a qualifying swim of at least 8 hours in cold water. Many pilots require evidence of cold water tolerance before they will accept a booking. Budget 2–3 years of preparation for most swimmers attempting this crossing."]'::jsonb,
  page_copy = '{"eyebrow":"Oceans Seven · Ireland / Scotland","difficulty_label":"Extreme","challenge_title":"What Makes It So Hard","benchmarks_label":"Training Benchmarks","readiness_title":"Check My North Channel Readiness","readiness_blurb":"Enter your current training state for an indicative readiness score.","cta_title":"Track your North Channel preparation","cta_blurb":"Log cold water swims, track your longest sessions and build a readiness record with SwimLoading — the water temperature tracker built for open water swimmers."}'::jsonb,
  faqs = '[{"q":"Why is the North Channel harder than the English Channel?","a":"The English Channel is 2–4°C warmer and has virtually no lion''s mane jellyfish. The North Channel''s combination of cold water, powerful tides and jellyfish makes it significantly harder — most open water experts rate it the hardest of the Oceans Seven."},{"q":"How do you deal with lion''s mane jellyfish?","a":"You don''t avoid them — you endure them. Some swimmers use a thin layer of lanolin for minor protection. Most accept stings as part of the crossing. Antihistamines are carried on escort boats but rarely eliminate the pain. Mental preparation for jellyfish contact is considered as important as physical training."},{"q":"How cold does the water get?","a":"The warmest recorded crossing-day temperatures are around 14°C in late August. July attempts often see 10–12°C. In cold years, even September water can be 11°C. The crossing requires sustained swimming through temperatures that would cause hypothermia within 1–2 hours for an untrained swimmer."},{"q":"What is the Oceans Seven?","a":"The Oceans Seven is marathon swimming''s equivalent of the Seven Summits — seven iconic channel crossings worldwide: English Channel, North Channel, Catalina Channel, Cook Strait, Molokai Channel, Tsugaru Strait and Strait of Gibraltar. The North Channel is widely regarded as the hardest of the seven."},{"q":"How do I book a North Channel attempt?","a":"Ratification is handled by the Irish Long Distance Swimming Association (ILDSA). Book an escort boat through a piloting and support operation such as Infinity Channel Swimming — pilots operate out of Donaghadee. Bookings are taken 12–18 months in advance for peak season windows. You will need evidence of a qualifying swim and cold-water experience before a pilot will accept your booking."}]'::jsonb,
  updated_at = now()
WHERE slug = 'north-channel';

UPDATE public.crossings SET
  intro = 'The world''s largest open water swimming event, drawing over 2,500 participants each February for the 19.7km crossing from Cottesloe Beach to Thomson Bay on Rottnest Island. Open to solos, duos, and teams of four.',
  seo_description = 'Complete guide to the Rottnest Channel Swim — 19.7km from Cottesloe Beach to Thomson Bay, Rottnest Island. The world''s largest open water swim event with 2,500+ participants each February.',
  key_facts = '[{"label":"Distance","val":"19.7 km","note":"Cottesloe Beach to Thomson Bay, Rottnest Island. The official course is measured and consistent each year."},{"label":"Water Temperature","val":"18–22°C","note":"February is late summer in Western Australia. The Leeuwin Current brings warm water down from the north, moderating conditions."},{"label":"Swim Season","val":"February","note":"The event runs on a single weekend each February. Solo, duo, and team-of-four categories all depart in waves across two days."},{"label":"Average Finish Time","val":"4–7 hrs (solo)","note":"Elite solo record under 4 hours. Most recreational solos finish in 5–8 hours. Team-of-four median around 3.5 hours."},{"label":"Participants","val":"2,500+","note":"The largest open water swim event by participant numbers in the world. Entries sell out within hours of opening each year."},{"label":"Difficulty","val":"Hard","note":"Challenging for solos due to distance and swell exposure, but warmer temperatures and the event''s support infrastructure make it more accessible than most marathon crossings."}]'::jsonb,
  prep_benchmarks = '["Longest single open water swim of at least 12–15km before race day.","Consistent weekly volume of 25–35km in the 8 weeks prior to the event.","Swell training: practise in ocean swells to adapt your stroke rhythm and breathing to a moving waterline.","Feed practice: can you eat and drink from a kayak or boat while treading water or swimming slowly? Practise this in open water.","For duo and team entries, coordination and transition drills between swimmers in open water are important."]'::jsonb,
  preparation = '["Unlike many marathon crossings, the Rottnest Swim takes place in relatively warm water (18–22°C), which removes the cold water acclimatisation demand that dominates preparation for northern hemisphere crossings. The primary training focus for solos is distance endurance and swell tolerance. If you''re training in protected pool or harbour water, build in at least one long ocean swim per week through your preparation block to adapt to the physical and psychological demands of open water movement.","Nutrition planning is as important as physical preparation for solos. A 5–7 hour swim in summer heat requires disciplined hydration and carbohydrate intake. Most experienced Rottnest soloists take a liquid feed (electrolyte drink with maltodextrin) every 20–30 minutes. Brief the paddler supporting you in water on your feeding schedule and what to watch for — signs of heat stress, salt intake, and stroke count degradation are the key indicators your paddler should monitor."]'::jsonb,
  page_copy = '{"eyebrow":"Western Australia — Indian Ocean","difficulty_label":"Hard","challenge_title":"What Makes It Challenging","benchmarks_label":"Training Benchmarks (Solo)","readiness_title":"Rottnest Readiness Check","readiness_blurb":"Enter your current training stats for an indicative solo readiness score. Duo and team swimmers can use this as a guide for their individual leg distance (roughly 10km and 5km respectively).","cta_title":"Log Your Training Swims","cta_blurb":"Track water temperatures and open water sessions as you build toward the Rottnest Channel Swim. Every log counts toward your preparation record."}'::jsonb,
  updated_at = now()
WHERE slug = 'rottnest-channel';

UPDATE public.crossings SET
  intro = 'Swimming between Europe and Africa across the world''s busiest shipping strait — ~14km from Tarifa, Spain to Ceuta on the Moroccan coast. Deceptively short on paper, the Strait of Gibraltar''s powerful currents, vessel traffic, and Levante wind make it a genuine challenge and a prized Oceans Seven crossing.',
  seo_description = 'Complete guide to swimming the Strait of Gibraltar — ~14km from Tarifa, Spain to Ceuta, Morocco. One of the Oceans Seven, with one of the world''s busiest shipping lanes and powerful Atlantic–Mediterranean currents.',
  key_facts = '[{"label":"Distance","val":"~14 km","note":"Tarifa, Spain to Ceuta (Spanish territory, Morocco). The actual distance swum is often 20–25km due to the diagonal current pushing swimmers east toward the Mediterranean."},{"label":"Water Temperature","val":"18–22°C","note":"Atlantic water enters the strait from the west, maintaining moderate temperatures year-round. July–September offers the warmest conditions at 20–22°C."},{"label":"Swim Season","val":"Jun – Oct","note":"Peak season July–September. The Levante (easterly wind) can close the strait for days at a time — weather windows of calm or westerly winds must be seized quickly."},{"label":"Average Finish Time","val":"3–5 hrs","note":"Record under 3 hours. Most swimmers finish in 3.5–5 hours. Fast finishes require favourable eastward current management — slow finishes occur when the current works against the swimmer."},{"label":"Governing Body","val":"ACNEG","note":"Asociación Cruce a Nado del Estrecho de Gibraltar. All ratified crossings must be sanctioned by ACNEG and use an approved pilot and observer."},{"label":"Difficulty","val":"Hard","note":"One of the Oceans Seven and considered one of the more accessible of the seven — but \"accessible\" is relative. Shipping traffic and the Levante wind have defeated many attempts."}]'::jsonb,
  prep_benchmarks = '["Longest single open water swim of at least 10km — the strait itself is short, but unpredictable conditions can extend a crossing significantly.","Weekly training volume of 20–30km, with a strong emphasis on rough water and chop tolerance.","Sustained pace swimming: Gibraltar rewards faster swimmers who can fight the eastward current drift and maintain a straight line. Speed matters more here than in pure endurance crossings.","Experience waiting and restarting: mental preparation for days of waiting at Tarifa, then going from rest to a race-pace start when a window opens."]'::jsonb,
  preparation = '["Gibraltar is unusual among the Oceans Seven in that it genuinely rewards faster swimmers. A swimmer maintaining 3km/h or more can use the current effectively and aim directly for Ceuta; a slower swimmer is carried progressively east and either misses Ceuta or swims a significantly longer diagonal arc. If your open water pace is below 2.5km/h, you will likely need the current to carry you to the African coast east of the planned finish, and your pilot must account for this in setting your start angle. Discuss your realistic pace honestly with your pilot before the crossing.","The most important preparation beyond fitness is logistics: registering with ACNEG well in advance, booking accommodation in Tarifa with flexible check-out (plan for a minimum one week stay to allow for weather waits), and engaging an ACNEG-approved pilot early in the season as experienced pilots have limited availability. Tarifa has a well-established community of Gibraltar crossing operators and support infrastructure — it is the most logistically straightforward of the Oceans Seven to organise."]'::jsonb,
  page_copy = '{"eyebrow":"Spain / Morocco — Oceans Seven","difficulty_label":"Hard","challenge_title":"What Makes It Challenging","benchmarks_label":"Training Benchmarks","readiness_title":"Gibraltar Readiness Check","readiness_blurb":"Enter your current training stats. Gibraltar rewards pace and rough-water adaptability more than raw endurance distance — speed and chop tolerance are the key differentiators.","cta_title":"Build Your Open Water Log","cta_blurb":"Track every training swim and water temperature as you build toward your Gibraltar crossing. Your ACNEG application will be stronger with a documented swim history."}'::jsonb,
  updated_at = now()
WHERE slug = 'strait-of-gibraltar';

UPDATE public.crossings SET
  intro = 'The 19.5km crossing between Japan''s Honshu and Hokkaido islands is the most logistically complex of the Oceans Seven — an intensely bureaucratic process, a brief annual window, violent currents, and cold upwelling that can drop water temperature by 8°C mid-crossing without warning.',
  seo_description = 'Complete guide to swimming the Tsugaru Strait — 19.5km from Honshu to Hokkaido, Japan. One of the Oceans Seven, with brutal cold upwelling, 15–20°C surface water masking sudden drops, and powerful currents.',
  key_facts = '[{"label":"Distance","val":"19.5 km","note":"Tappi Saki, Honshu to Shirakami Misaki, Hokkaido. Strong currents mean the actual distance swum is often significantly longer as swimmers are pushed off the straight-line route."},{"label":"Water Temperature","val":"15–20°C","note":"Surface water in August–September reaches 18–20°C, but cold upwelling from the Tsugaru Current can plunge temperatures to 10–12°C at any moment. The real cold risk is unpredictable, not constant."},{"label":"Swim Season","val":"Aug – Sep","note":"The viable window is extremely narrow — effectively August and early September. Outside this, typhoon season, cold water, and severe currents make the crossing practically impossible."},{"label":"Average Finish Time","val":"7–12 hrs","note":"Record: 7h 6m. Many swimmers take 10–13 hours due to current drift adding significant distance. Some attempts never reach Hokkaido despite hours of effort against adverse currents."},{"label":"Governing Body","val":"TCSA","note":"Tsugaru Channel Swimming Association (津軽海峡水泳協会). Japanese-language coordination required. TCSA manages all sanctions, observer assignments, and liaison with Japan Coast Guard."},{"label":"Difficulty","val":"Very Hard","note":"One of the Oceans Seven. The primary difficulty is not the distance but the current variability, cold upwelling, logistical complexity, and the extraordinarily brief annual weather window."}]'::jsonb,
  prep_benchmarks = '["Sustained swimming in cold water, including experience with sudden temperature drops — acclimatise to entering 10–12°C water after extended swimming in 18–20°C water.","Longest single open water swim of at least 15km in exposed ocean conditions.","Weekly volume of 35–45km maintained through the spring and summer before your attempt.","Typhoon contingency planning: physical readiness to attempt on any viable day within your window means being match-fit for the entire 2–3 week stay in Japan.","Begin TCSA contact and logistics at least 12–18 months before your target season — the paperwork and permits required are substantial."]'::jsonb,
  preparation = '["The cold upwelling hazard unique to the Tsugaru Strait deserves specific preparation attention. Unlike Cook Strait where the water is consistently cold throughout, Tsugaru can feel like warm water swimming for hours before suddenly delivering a pocket of 10°C deep water. The physiological shock of this transition — when your body has been warm and relaxed — can be more dangerous than sustained cold water swimming. Train specifically for this by practising deliberate transitions from warm to cold water during long sessions, building your nervous system''s ability to adapt quickly without panicking or losing stroke efficiency.","Logistics preparation should begin 12–18 months before your target crossing season. Contact the TCSA (ideally through a Japanese-speaking channel) to understand the current requirements for sanctioned attempts. Engage an experienced Japanese escort boat captain — the pool of operators willing and permitted to escort marathon swimmers in this heavily regulated strait is small. Many international swimmers work through a Japan-based open water swimming contact or sports tourism operator who can navigate the bureaucratic requirements. Budget substantially more time and money than for any other Oceans Seven crossing for the logistics phase alone."]'::jsonb,
  page_copy = '{"eyebrow":"Japan — Oceans Seven","difficulty_label":"Very Hard","challenge_title":"What Makes It Challenging","benchmarks_label":"Training Benchmarks","readiness_title":"Tsugaru Readiness Check","readiness_blurb":"Enter your current training stats. Tsugaru demands particular readiness for sudden cold water exposure — even if surface temperatures feel manageable, upwelling can test cold tolerance at any point in the crossing.","cta_title":"Document Every Cold Water Swim","cta_blurb":"Your TCSA application and Oceans Seven ratification will be stronger with a detailed log of cold water sessions and open water temperatures. Start building that record now."}'::jsonb,
  updated_at = now()
WHERE slug = 'tsugaru-strait';

COMMIT;

